import { InvalidOptionError } from "./errors.ts";
import type { Pattern, Preset, SelectorOptions } from "./types.ts";

/** Classes that describe runtime state or are generated by tooling, so never identify a node. */
export const DEFAULT_CLASS_DENY_LIST: readonly RegExp[] = Object.freeze([
  /^(active|current|selected|checked|disabled|focus|focused|hover|open|opened|closed|collapsed|expanded|hidden|hide|show|shown|visible|invisible|loaded|loading|appear|animated|fade|in|out)$/,
  /^(is|has|no|js)-/,
  /^\d/,
  // emotion, styled-components, styled-jsx, Svelte and Angular runtime classes
  /^(css|sc|jsx|svelte|ng)-/,
  // CSS Modules hash suffix, e.g. Button_title__a1b2c
  /__[\w-]*\d[\w-]*$/,
  /\d{4,}|(^|[-_])[0-9a-f]{8,}($|[-_])/i,
]);

/**
 * Generated-looking ids: leading digit, 4+ digit runs, long hex tokens and React `useId` values
 * (`:r1:`, `«r1»`, `_r_1_`).
 */
export const DEFAULT_ID_DENY_PATTERN: RegExp =
  /^\d|\d{4,}|(^|[-_])[0-9a-f]{8,}($|[-_])|:r[0-9a-z]*:|«r[0-9a-z]*»|^_r_[0-9a-z]+_$/i;

/** Option bundles for specific site platforms. Spread one into `createSelectorContext`. */
export const presets: Readonly<{ milo: Preset }> = Object.freeze({
  /** Adobe Milo / Franklin blocks: deny-lists runtime decoration classes such as `con-block`. */
  milo: Object.freeze({
    classDenyList: Object.freeze([
      /^(con-block|has-bg|center|dark|light|dark-bg|light-bg|grid|appear|visible|loaded|active|open|hidden|hide|show)$/,
      /^(xxs|xs|s|m|l|xl|xxl)-(spacing|spacing-static)(-top|-bottom)?$/,
      /^(is|has|no|hide|show)-/,
      /-(up|down|left|right)$/,
      /^\d/,
    ]),
    idDenyPattern: /^\d|\d{4,}|(^|[-_])[0-9a-f]{8,}($|[-_])/i,
  }),
});

export interface ResolvedOptions {
  classDeny: RegExp[];
  idDeny: RegExp;
  attributes: string[];
}

function toRegExp(entry: unknown, name: string): RegExp {
  if (entry instanceof RegExp) {
    // A global or sticky RegExp keeps `lastIndex` between `test` calls, which would make
    // matching depend on call order.
    return /[gy]/.test(entry.flags)
      ? new RegExp(entry.source, entry.flags.replace(/[gy]/g, ""))
      : entry;
  }
  if (typeof entry === "string") {
    try {
      return new RegExp(entry);
    } catch (error) {
      throw new InvalidOptionError(`${name} contains an invalid pattern: ${entry}`, {
        cause: error,
      });
    }
  }
  throw new InvalidOptionError(
    `${name} entries must be RegExp or string, received ${typeof entry}`,
  );
}

export function resolveOptions(options: SelectorOptions): ResolvedOptions {
  const { classDenyList, idDenyPattern, attributes } = options;
  if (classDenyList != null && !Array.isArray(classDenyList)) {
    throw new InvalidOptionError("classDenyList must be an array of RegExp or string patterns");
  }
  if (attributes != null) {
    if (!Array.isArray(attributes)) {
      throw new InvalidOptionError("attributes must be an array of attribute names");
    }
    for (const name of attributes) {
      if (typeof name !== "string" || name.trim() === "") {
        throw new InvalidOptionError("attributes must contain non-empty attribute names");
      }
    }
  }
  return {
    classDeny: (classDenyList ?? DEFAULT_CLASS_DENY_LIST).map((entry: Pattern) =>
      toRegExp(entry, "classDenyList"),
    ),
    idDeny: toRegExp(idDenyPattern || DEFAULT_ID_DENY_PATTERN, "idDenyPattern"),
    attributes: attributes ? [...attributes] : [],
  };
}
